package com.companages.service;
import com.companages.entity.*; import com.companages.exception.*; import com.companages.repository.*; import org.springframework.stereotype.Service;
@Service public class OrganizationAccessService { private final MemberRepository members; private final CurrentUserService current; public OrganizationAccessService(MemberRepository m,CurrentUserService c){members=m;current=c;} public Member requireMember(Long organizationId){return members.findByOrganizationIdAndUserId(organizationId,current.get().getId()).orElseThrow(()->new ResourceNotFoundException("Organization not found"));} public Member requireAny(Long organizationId,AccessRole... roles){Member member=requireMember(organizationId);for(AccessRole role:roles)if(member.getAccessRole()==role)return member;throw new ForbiddenException("You do not have permission to perform this action");} public Member requireAdmin(Long organizationId){return requireAny(organizationId,AccessRole.OWNER,AccessRole.ADMIN);} public Member requireManager(Long organizationId){return requireAny(organizationId,AccessRole.OWNER,AccessRole.ADMIN,AccessRole.MANAGER);} public Member requireOwner(Long organizationId){return requireAny(organizationId,AccessRole.OWNER);} }
